result.output:
300	        }
301	
302	        // Usage arrives on the final chunk (after `include_usage: true`) and
303	        // is emitted inline as it arrives. Finish is deferred to finish() at
304	        // end-of-stream — see this function's doc comment.
305	        if let Some(u) = chunk.usage.as_ref() {
306	            out.push(ModelEvent::Usage {
307	                input_tokens: u.prompt_tokens,
308	                output_tokens: u.completion_tokens,
309	                cached_input_tokens: u
310	                    .prompt_tokens_details
311	                    .as_ref()
312	                    .and_then(|d| d.cached_tokens),
313	                reasoning_tokens: u
314	                    .completion_tokens_details
315	                    .as_ref()
316	                    .and_then(|d| d.reasoning_tokens),
317	            });
318	        }
319	
320	        out
321	    }
322	
323	    /// Emit the terminal `Finish` at end-of-stream.
324	    ///
325	    /// Returns an empty vec when no `finish_reason` was ever observed, so a
326	    /// truncated stream is never reported as a clean stop, or when an
327	    /// earlier call already drained the buffer.
328	    pub(crate) fn finish(&mut self) -> Vec<ModelEvent> {
329	        let Some(reason) = self.finish_reason.take() else {
330	            tracing::debug!(
331	                target: "paigasus::openai::chat",
332	                "stream ended without a finish_reason; emitting no Finish"
333	            );
334	            return Vec::new();
335	        };
336	        vec![ModelEvent::Finish { reason }]
337	    }
338	
339	    fn handle_tool_call_chunk(
340	        &mut self,
341	        tc: &ChatCompletionMessageToolCallChunk,
342	        out: &mut Vec<ModelEvent>,
343	    ) {
344	        let index = tc.index;
345	        let call_id_known = self.tool_calls.contains_key(&index);
346	
347	        // Resolve or register the call_id.
348	        let call_id = if call_id_known {
349	            self.tool_calls[&index].clone()
350	        } else if let Some(id) = tc.id.as_deref() {
351	            self.tool_calls.insert(index, id.to_owned());
352	            id.to_owned()
353	        } else {
354	            // No call_id known yet and none on this delta — buffer both name
355	            // and args so neither is silently dropped. They will be flushed
356	            // into the first ToolCallDelta once the id arrives.
357	            let entry = self.pending.entry(index).or_default();
358	            if let Some(fname) = tc.function.as_ref().and_then(|f| f.name.as_deref()) {
359	                entry.name.push_str(fname);
360	            }
361	            if let Some(adelta) = tc.function.as_ref().and_then(|f| f.arguments.as_deref()) {
362	                entry.args.push_str(adelta);
363	            }
364	            return;
365	        };
366	
367	        // Flush any name/args buffered before the call_id arrived.
368	        let PendingToolCall {
369	            name: buffered_name,
370	            args: buffered_args,
371	        } = self.pending.remove(&index).unwrap_or_default();
372	
373	        // Emit name on the first delta that has it (and only once per index).
374	        // Concatenate any buffered pre-id fragments with the current chunk's
375	        // name fragment so neither is dropped (mirrors args concatenation).
376	        let current_name = tc
377	            .function
378	            .as_ref()
379	            .and_then(|f| f.name.as_deref())
380	            .unwrap_or("");
381	        let name_to_emit = if self.name_emitted.contains(&index) {
382	            None
383	        } else if !buffered_name.is_empty() || !current_name.is_empty() {
384	            let mut name = buffered_name;
385	            name.push_str(current_name);
386	            self.name_emitted.insert(index);
387	            Some(name)
388	        } else {
389	            None
390	        };
391	
392	        // Prepend any buffered args to the current chunk's args delta.
393	        let current_delta = tc
394	            .function
395	            .as_ref()
396	            .and_then(|f| f.arguments.as_deref())
397	            .unwrap_or("");
398	        let args_delta = if buffered_args.is_empty() {
399	            current_delta.to_owned()
400	        } else {
401	            buffered_args + current_delta
402	        };
403	
404	        out.push(ModelEvent::ToolCallDelta {
405	            call_id,
406	            name: name_to_emit,
407	            args_delta,
408	        });
409	    }
410	}
