481	/// Accumulates the in-progress tool call across `ModelEvent::ToolCallDelta`
482	/// chunks for one `call_id`.
483	#[derive(Debug, Default)]
484	struct ToolCallAccum {
485	    name: Option<String>,
486	    args_str: String,
487	}
488	
489	/// Reassemble streamed model output into [`crate::Item`]s.
490	fn build_items(
491	    agent_name: &str,
492	    text: String,
493	    reasoning: String,
494	    tool_accum: std::collections::BTreeMap<String, ToolCallAccum>,
495	) -> Result<Vec<crate::Item>, String> {
496	    let mut items = Vec::new();
497	    if !text.is_empty() || !reasoning.is_empty() {
498	        let mut content = Vec::new();
499	        if !reasoning.is_empty() {
500	            content.push(crate::ContentPart::Reasoning { text: reasoning });
501	        }
502	        if !text.is_empty() {
503	            content.push(crate::ContentPart::Text { text });
504	        }
505	        items.push(crate::Item::AssistantMessage {
506	            content,
507	            agent: Some(agent_name.to_owned()),
508	        });
509	    }
510	    for (call_id, accum) in tool_accum {
511	        // OpenAI streaming legitimately emits an empty `arguments` delta for
512	        // zero-parameter tool calls — normalize blank/whitespace-only args to
513	        // `{}` rather than failing the whole turn on a `serde_json` EOF error.
514	        let args_str = if accum.args_str.trim().is_empty() {
515	            "{}"
516	        } else {
517	            accum.args_str.as_str()
518	        };
519	        let args = serde_json::from_str(args_str).map_err(|e| {
520	            format!(
521	                "invalid tool args for call_id={call_id} (name={}): {e}",
522	                accum.name.as_deref().unwrap_or("?")
523	            )
524	        })?;
525	        items.push(crate::Item::ToolCall {
526	            call_id,
527	            name: accum.name.unwrap_or_default(),
528	            args,
529	        });
530	    }
531	    Ok(items)
532	}
