534	/// Accumulates a streamed model response into a [`ModelTurn`].
535	///
536	/// Feed every successful [`ModelEvent`] from a [`Model::invoke`] stream via
537	/// [`Self::observe`], then call [`Self::finish`] once the stream ends (after
538	/// observing a `Finish` event) to reassemble the turn's [`crate::Item`]s.
539	#[derive(Debug)]
540	pub struct ModelTurnAccumulator {
541	    agent_name: String,
542	    text: String,
543	    reasoning: String,
544	    tool_accum: std::collections::BTreeMap<String, ToolCallAccum>,
545	    finish_reason: FinishReason,
546	    latest_usage: Option<crate::TokenUsage>,
547	}
548	
549	impl ModelTurnAccumulator {
550	    /// Start a new accumulator. `agent_name` is attributed to the
551	    /// resulting turn's `AssistantMessage`, if any.
552	    pub fn new(agent_name: impl Into<String>) -> Self {
553	        Self {
554	            agent_name: agent_name.into(),
555	            text: String::new(),
556	            reasoning: String::new(),
557	            tool_accum: std::collections::BTreeMap::new(),
558	            finish_reason: FinishReason::Stop,
559	            latest_usage: None,
560	        }
561	    }
562	
563	    /// Feed one successful model event. `Err(ModelEvent)`s are the caller's
564	    /// concern — this only observes `Ok` events from the stream.
565	    pub fn observe(&mut self, event: &ModelEvent) {
566	        match event {
567	            ModelEvent::TokenDelta { text } => self.text.push_str(text),
568	            ModelEvent::ReasoningDelta { text } => self.reasoning.push_str(text),
569	            ModelEvent::ToolCallDelta {
570	                call_id,
571	                name,
572	                args_delta,
