1	//! SSE chunk → [`ModelEvent`] translation.
2	//!
3	//! Two invariants carry this module:
4	//!
5	//! 1. **`Finish` is emitted only from [`ChatTranslator::finish`]**, called at
6	//!    `[DONE]`/EOF — never inline with a chunk. With
7	//!    `stream_options.include_usage`, the usage snapshot arrives in a chunk
8	//!    *after* the one carrying `finish_reason`, so an inline `Finish` would be
9	//!    followed by `Usage` and violate core's "Finish is the terminal event"
10	//!    contract on every turn.
11	//! 2. **Tool-call `name`/`arguments` are buffered until the `id` is known**,
12	//!    because the id is not guaranteed to arrive first, and both fields
13	//!    fragment across deltas. A delta that carries neither `index` nor `id`
14	//!    is correlated by its position within `delta.tool_calls`, but only
15	//!    when *no* entry in that same array carries an explicit `index` — a
16	//!    synthesized positional key must never be allowed to collide with a
17	//!    genuine explicit index elsewhere in the array, which would silently
18	//!    merge two distinct calls. A mixed array (some entries indexed, one
19	//!    not) is non-conforming for OpenAI-compatible streaming; the
20	//!    ambiguous entry is skipped with a loud warning rather than guessed.
21	
22	use std::collections::{HashMap, HashSet};
23	
24	use paigasus_helikon_core::{FinishReason, ModelEvent};
25	
26	use crate::sse::{StreamChunk, ToolCallChunk};
27	
28	/// Correlation key for a streaming tool call.
29	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
30	enum Key {
31	    /// Correlated by `delta.tool_calls[].index`, when present — or, as a
32	    /// last resort, by position within `delta.tool_calls` (in OpenAI-
33	    /// compatible streaming the array position *is* the index, so a
34	    /// positional continuation delta correctly joins a call already keyed
35	    /// by `Index`).
36	    Index(u32),
37	    /// Correlated by `delta.tool_calls[].id`, when `index` is absent.
38	    Id(String),
39	}
40	
41	/// Name/args fragments that arrived before the `id` was known.
42	#[derive(Default)]
43	struct Pending {
44	    /// Accumulated function-name fragments.
45	    name: String,
46	    /// Accumulated JSON-arguments fragments.
47	    args: String,
48	}
49	
50	/// Accumulates SSE deltas and produces [`ModelEvent`]s.
51	///
52	/// One instance tracks a single streamed response. `consume` is called once
53	/// per chunk in order; `finish` is called once at stream end (`[DONE]` or
54	/// EOF) to emit the terminal event, if any.
55	pub(crate) struct ChatTranslator {
56	    /// Resolved call ids, keyed by correlation [`Key`].
57	    tool_calls: HashMap<Key, String>,
58	    /// Keys for which a tool-call `name` has already been emitted.
59	    name_emitted: HashSet<Key>,
60	    /// Name/args fragments buffered until the call's `id` is known.
61	    pending: HashMap<Key, Pending>,
62	    /// The most recent `finish_reason` observed, buffered until [`Self::finish`].
63	    finish_reason: Option<String>,
64	    /// Whether the multi-choice warning has already fired for this stream.
65	    warned_multi_choice: bool,
66	}
67	
68	impl ChatTranslator {
69	    /// Construct a translator with empty state.
70	    pub(crate) fn new() -> Self {
71	        Self {
72	            tool_calls: HashMap::new(),
73	            name_emitted: HashSet::new(),
74	            pending: HashMap::new(),
75	            finish_reason: None,
76	            warned_multi_choice: false,
77	        }
78	    }
79	
80	    /// Consume one chunk. Never emits `Finish`.
81	    pub(crate) fn consume(&mut self, chunk: StreamChunk) -> Vec<ModelEvent> {
82	        let mut out = Vec::new();
83	
84	        if chunk.choices.len() > 1 && !self.warned_multi_choice {
85	            self.warned_multi_choice = true;
86	            tracing::warn!(
87	                target: "paigasus::litellm::stream",
88	                n = chunk.choices.len(),
89	                "response carries multiple choices; only the first is read"
90	            );
91	        }
92	
93	        if let Some(choice) = chunk.choices.first() {
94	            if let Some(delta) = &choice.delta {
95	                if let Some(text) = delta.content.as_deref().filter(|s| !s.is_empty()) {
96	                    out.push(ModelEvent::TokenDelta {
97	                        text: text.to_owned(),
98	                    });
99	                }
100	                let reasoning = delta
101	                    .reasoning_content
102	                    .as_deref()
103	                    .or(delta.reasoning.as_deref())
104	                    .filter(|s| !s.is_empty());
105	                if let Some(text) = reasoning {
106	                    out.push(ModelEvent::ReasoningDelta {
107	                        text: text.to_owned(),
108	                    });
109	                }
110	                if let Some(tcs) = &delta.tool_calls {
111	                    // A positional key is only safe to synthesize when no
112	                    // entry in *this* array carries an explicit `index` —
113	                    // otherwise a synthesized `Key::Index(pos)` can collide
114	                    // with a genuine explicit index elsewhere in the same
115	                    // array. See the module docs.
116	                    let any_explicit_index = tcs.iter().any(|tc| tc.index.is_some());
117	                    for (pos, tc) in tcs.iter().enumerate() {
118	                        self.handle_tool_call(tc, pos, any_explicit_index, &mut out);
119	                    }
120	                }
121	            }
122	            if let Some(reason) = &choice.finish_reason {
123	                // Buffered — see the module docs.
124	                self.finish_reason = Some(reason.clone());
125	            }
126	        }
127	
128	        if let Some(u) = &chunk.usage {
129	            out.push(ModelEvent::Usage {
130	                input_tokens: u.prompt_tokens,
131	                output_tokens: u.completion_tokens,
132	                cached_input_tokens: u
133	                    .prompt_tokens_details
134	                    .as_ref()
135	                    .and_then(|d| d.cached_tokens),
136	                reasoning_tokens: u
137	                    .completion_tokens_details
138	                    .as_ref()
139	                    .and_then(|d| d.reasoning_tokens),
140	            });
141	        }
142	
143	        out
144	    }
145	
146	    fn handle_tool_call(
147	        &mut self,
148	        tc: &ToolCallChunk,
149	        pos: usize,
150	        any_explicit_index: bool,
151	        out: &mut Vec<ModelEvent>,
152	    ) {
153	        let key = match (tc.index, tc.id.as_deref()) {
154	            (Some(i), _) => Key::Index(i),
155	            (None, Some(id)) => Key::Id(id.to_owned()),
156	            (None, None) if any_explicit_index => {
157	                // A synthesized positional key would risk colliding with a
158	                // genuine explicit `index` elsewhere in this same array
159	                // (e.g. entry 0 explicitly `index: 1`, entry 1 has neither
160	                // — pos 1 would collide with `Key::Index(1)`). That mixes
161	                // two distinct calls into one and corrupts both, which is
162	                // worse than dropping this entry, so skip it loudly.
163	                tracing::warn!(
164	                    target: "paigasus::litellm::stream",
165	                    pos,
166	                    "tool-call delta at this position has neither index nor id, and \
167	                     another entry in the same array carries an explicit index; \
168	                     skipping to avoid a key collision"
169	                );
170	                return;
171	            }
172	            (None, None) => {
173	                tracing::debug!(
174	                    target: "paigasus::litellm::stream",
175	                    pos,
176	                    "tool-call delta has neither index nor id; correlating by position"
177	                );
178	                Key::Index(pos as u32)
179	            }
180	        };
181	
182	        let name_frag = tc.function.as_ref().and_then(|f| f.name.as_deref());
183	        let args_frag = tc.function.as_ref().and_then(|f| f.arguments.as_deref());
184	
185	        if let Some(id) = tc.id.as_deref() {
186	            self.tool_calls
187	                .entry(key.clone())
188	                .or_insert_with(|| id.to_owned());
189	        }
190	
191	        let Some(call_id) = self.tool_calls.get(&key).cloned() else {
192	            // No id yet — buffer both fragments.
193	            let slot = self.pending.entry(key).or_default();
194	            if let Some(n) = name_frag {
195	                slot.name.push_str(n);
196	            }
197	            if let Some(a) = args_frag {
198	                slot.args.push_str(a);
199	            }
200	            return;
201	        };
202	
203	        let buffered = self.pending.remove(&key).unwrap_or_default();
204	        let mut name = buffered.name;
205	        if let Some(n) = name_frag {
206	            name.push_str(n);
207	        }
208	        let mut args = buffered.args;
209	        if let Some(a) = args_frag {
210	            args.push_str(a);
211	        }
212	
213	        let emit_name = if self.name_emitted.contains(&key) || name.is_empty() {
214	            None
215	        } else {
216	            self.name_emitted.insert(key.clone());
217	            Some(name)
218	        };
219	
220	        if emit_name.is_none() && args.is_empty() {
221	            return;
222	        }
223	
224	        out.push(ModelEvent::ToolCallDelta {
225	            call_id,
226	            name: emit_name,
227	            args_delta: args,
228	        });
229	    }
